{
  "families": [
    {
      "family": "pipelined",
      "ranges": [
        {"param": "data_width", "low": 14, "high": 20, "choices": null},
        {"param": "n_iter", "low": 12, "high": 22, "choices": null},
        {"param": "angle_guard", "low": -1, "high": 2, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 2, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 0.6,
      "why": "Only a fully-pipelined family can plausibly satisfy throughput_msps >= 250: it emits 1 result/cycle so throughput == Fmax, and a one-stage-per-micro-rotation schedule has the shortest logic depth per stage, giving the best chance of Fmax >= 250 MHz on Artix-7. It is also the natural accuracy reference (identical bit behaviour to all other families). Ranges: data_width 14-20 brackets the 2^-13 error floor (LSB = 2^-(W-2)); n_iter 12-22 covers the angle-resolution requirement for those widths; small positive angle_guard/frac_guard are allowed to buy accuracy without much area; both rounding modes are searched since rounding can shave a bit of error for free."
    },
    {
      "family": "pipelined_m",
      "ranges": [
        {"param": "data_width", "low": 14, "high": 20, "choices": null},
        {"param": "n_iter", "low": 12, "high": 22, "choices": null},
        {"param": "angle_guard", "low": -1, "high": 2, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 2, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "m", "low": 2, "high": 4, "choices": null}
      ],
      "budget_share": 0.4,
      "why": "Same 1-result/cycle throughput as pipelined, but registering every m stages trades logic depth (hence Fmax) against register count. Since the objective is min LUTs (not FFs), this family may reach a lower-LUT point on the front if the extra combinational depth still clears 250 MHz; m is kept small (2-4) because larger m risks dropping below the 250 MSPS constraint. Same accuracy ranges as pipelined because accuracy is family-independent."
    }
  ],
  "rationale": "The spec is throughput-bound: >= 250 MSPS with one sample per clock. iterative (N+3 cycles/result) and unrolled_k (ceil(N/k)+3 cycles/result) cannot reach 250 MSPS at any plausible Artix-7 Fmax, so they are excluded from round 1 and would only be revisited if the pipelined families prove infeasible. Both pipelined families emit 1 result/cycle, so the throughput constraint reduces to Fmax >= 250 MHz, and the accuracy constraint (max_abs_err <= 2^-13) is met by choosing data_width/n_iter/guards. Round 1 therefore spends the whole 100-eval budget on pipelined (60%) and pipelined_m (40%), with data_width 14-20 and n_iter 12-22 to bracket the error floor, small guard ranges, and both rounding modes. This should reveal whether the feasible front is a single corner (min-LUT design at the accuracy/throughput edge) or a genuine trade-off curve, which then drives the range refinement in later rounds."
}

{
  "decision": "add_family",
  "rationale": "Only `pipelined` can satisfy the 250 MSPS constraint: it is the sole feasible family (max throughput 273 MSPS), while `pipelined_m` is 0/40 feasible with max throughput 171 MSPS — registering every m stages lengthens the combinational path and drops Fmax below the target. The two unexplored families are structurally throughput-limited: `iterative` needs N+3 cycles/result (N=15 → ~15 MSPS even at pipelined's 273 MHz), and `unrolled_k` needs ceil(N/k)+3 cycles/result (best case N≤k → 4 cycles → needs Fmax ≥ 1000 MHz, far above the 273 MHz pipelined achieves, and chaining k rotations per cycle lowers Fmax further). They are therefore very likely infeasible, but they are the only untested families and a shared-datapath family could in principle beat pipelined's 971 LUTs — which matters because the selection rule is min luts. Spend this round confirming that, then use the final round to map the pipelined front over its full ranges.",
  "next_plan": {
    "families": [
      {
        "family": "unrolled_k",
        "ranges": [
          {"param": "data_width", "low": 14, "high": 20, "choices": null},
          {"param": "n_iter", "low": 8, "high": 20, "choices": null},
          {"param": "angle_guard", "low": -1, "high": 3, "choices": null},
          {"param": "frac_guard", "low": 0, "high": 3, "choices": null},
          {"param": "rounding", "low": null, "high": null, "choices": ["round"]},
          {"param": "k", "low": 6, "high": 8, "choices": null}
        ]
      ,
      "budget_share": 0.6
      ,
      "why": "High k maximises results/cycle; test whether any k can reach 250 MSPS and whether shared datapath lowers LUTs below 971."
      },
      {
        "family": "iterative",
        "ranges": [
          {"param": "data_width", "low": 14, "high": 20, "choices": null},
          {"param": "n_iter", "low": 4, "high": 16, "choices": null},
          {"param": "angle_guard", "low": -1, "high": 3, "choices": null},
          {"param": "frac_guard", "low": 0, "high": 3, "choices": null},
          {"param": "rounding", "low": null, "high": null, "choices": ["round"]}
        ]
      ,
      "budget_share": 0.4
      ,
      "why": "Low N minimises cycles/result; confirm the N+3 schedule cannot reach 250 MSPS."
      }
    ],
    "rationale": "Explore the two untested families at their throughput-favourable corners (high k for unrolled_k, low N for iterative) to either find a lower-LUT feasible design or prove the front is pipelined-only. Keep pipelined's feasible ranges (data_width 16..20, n_iter 15..22, angle_guard -1..3, frac_guard 0..3) untouched for the reserved map_front round."
  }
}
